async function loadModels() {
    await faceapi.nets.faceRecognitionNet.loadFromDisk(MODEL_DIR);
    await faceapi.nets.faceLandmark68Net.loadFromDisk(MODEL_DIR);
    await faceapi.nets.ssdMobilenetv1.loadFromDisk(MODEL_DIR);
    console.log('Models loaded successfully.');
  }
  
  async function loadImageFromUrl(url) {
    const response = await axios.get(url, { responseType: 'arraybuffer' });
    const buffer = Buffer.from(response.data, 'binary');
    const img = await canvas.loadImage(buffer);
    return img;
  }

// Define FIR Schema
const firSchema = new mongoose.Schema({
  'Sr. No.': Number,
  'State': String,
  'District': String,
  'Police Station': String,
  'Year': Number,
  'FIR No': String,
  'Registration Date': String,
  'Sections': String
}, { collection: 'fir' }); // Specify the collection name here

const FIR = mongoose.model('fir', firSchema);

// Endpoints

const HERE_API_KEY = '0dTJ0gdlk6g9m0jMNs7hs4297YJWc3l2wlx9x7qm9Ls';

app.get('/api/route', async (req, res) => {
  const { start, end } = req.query;

  if (!start || !end) {
    return res.status(400).json({ error: 'Start and end coordinates are required' });
  }

  try {
    const response = await axios.get('https://router.hereapi.com/v8/routes', {
      params: {
        apiKey: HERE_API_KEY,
        transportMode: 'car',
        origin: start,
        destination: end,
        return: 'polyline'
      }
    });

    if (response.data.routes && response.data.routes.length > 0) {
      res.json(response.data);
    } else {
      console.log('HERE API Response:', response.data);
      res.status(404).json({ error: 'No route found', details: response.data });
    }
  } catch (error) {
    console.error('Error fetching route:', error.response?.data || error.message);
    res.status(500).json({ error: 'Unable to fetch route', details: error.response?.data || error.message });
  }
});

