// 1. Get all FIRs (with pagination)
app.get('/api/firs', async (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;
  const skip = (page - 1) * limit;

  try {
    const firs = await FIR.find().skip(skip).limit(limit);
    const fir = await FIR.findById('66d03bbd2c833de700be9d67');
    const total = await FIR.countDocuments();
    res.json({
      data: firs,
      currentPage: page,
      totalPages: Math.ceil(total / limit),
      totalRecords: total
    });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// 2. Get FIR by FIR No.
app.get('/api/fir', async (req, res) => {
    const firNo = req.query.firNo;
  
    if (!firNo) {
      return res.status(400).json({ message: 'FIR number is required' });
    }
  
    try {
      const fir = await FIR.findOne({ 'FIR No': firNo });
      if (fir) {
        res.json(fir);
      } else {
        res.status(404).json({ message: 'FIR not found' });
      }
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

// 3. Get FIRs by District
app.get('/api/firs/district/:district', async (req, res) => {
  const { page = 1, limit = 10 } = req.query; // Set default values for page and limit

  try {
    // Convert page and limit to integers
    const pageNumber = parseInt(page);
    const limitNumber = parseInt(limit);

    // Calculate the number of documents to skip
    const skip = (pageNumber - 1) * limitNumber;

    // Query the database with pagination
    const firs = await FIR.find({ District: req.params.district })
      .skip(skip) // Skip the documents
      .limit(limitNumber); // Limit the number of documents returned

    const total = await FIR.countDocuments({ District: req.params.district }); // Get total count of documents

    // Calculate total pages
    const totalPages = Math.ceil(total / limitNumber);

    // Send response
    res.json({
      totalPages,
      currentPage: pageNumber,
      data: firs,
    });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});


app.get('/api/weights', async (req, res) => {
  try {
    const districtCounts = await FIR.aggregate([
      {
        $group: {
          _id: "$District", // Group by the 'District' field
          count: { $sum: 1 } // Count the occurrences of each district
        }
      },
      {
        $project: {
          _id: 0, // Exclude _id from the result
          District: "$_id", // Rename _id to District
          count: 1 // Include the count field
        }
      }
    ]);

    // Convert the result into a key-value pair format
    const response = districtCounts.reduce((acc, item) => {
      acc[item.District] = item.count;
      return acc;
    }, {});

    res.json(response); // Send the response as JSON
  } catch (error) {
    console.error("Error fetching district counts:", error);
    res.status(500).json({ error: "An error occurred while fetching data" });
  }
});


