//6. Get FIRs for past 2 years
app.get('/api/firs/lastTwoYears', async (req, res) => {
  try {
      // Fetch data for the last two years
      const firs = await FIR.find({
          Year: { $in: [2023, 2024] }
      });

      // Initialize an empty object to store results
      let results = {};

      // Iterate through the fetched FIRs
      firs.forEach(fir => {
          // Extract the month and year from the registration date
          const registrationDate = new Date(fir["Registration Date"]);

          // Check if the date is valid
          if (isNaN(registrationDate.getTime())) {
              return; // Skip this record if the date is invalid
          }

          const month = registrationDate.toLocaleString('default', { month: 'long' });
          const year = fir.Year;

          // Initialize the month entry if it doesn't exist
          if (!results[month]) {
              results[month] = { month: month, year2023: 0, year2024: 0 };
          }

          // Increment the count for the respective year
          if (year === 2023) {
              results[month].year2023 += 1;
          } else if (year === 2024) {
              results[month].year2024 += 1;
          }
      });

      // Convert the results object to an array
      const responseData = Object.values(results);

      // Send the response
      res.json(responseData);
  } catch (error) {
      console.error('Error fetching FIR data:', error);
      res.status(500).json({ error: 'An error occurred' });
  }
});

// 5. Search FIRs by Section
app.get('/api/firs/search/section', async (req, res) => {
  const section = req.query.section;
  try {
    const firs = await FIR.find({ Sections: { $regex: section, $options: 'i' } });
    res.json(firs);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

