app.get('/api/arrestedSearch', async (req, res) => {
  const { DateFrom, DateTo, AgeFrom, AgeTo, DistrictNo, FirstName, MiddleName, LastName, GenderNo, PersonType } = req.query;

  try {
    // Step 1: Fetch the form page to get dynamic values
    const formResponse = await axios.get('https://citizen.mahapolice.gov.in/Citizen/MH/SearcgAccusedArrest.aspx');
    const cookies = formResponse.headers['set-cookie'];
    const $form = cheerio.load(formResponse.data);

    // Extract dynamic form data like VIEWSTATE
    const viewState = $form('#__VIEWSTATE').val();
    const eventValidation = $form('#__EVENTVALIDATION').val();

    // Step 2: Prepare the POST data
    let data = qs.stringify({
      '__ASYNCPOST': 'true',
      '__EVENTARGUMENT': '',
      '__EVENTTARGET': '',
      '__EVENTVALIDATION': eventValidation,
      '__VIEWSTATE': viewState,
      '__VIEWSTATEGENERATOR': $form('#__VIEWSTATEGENERATOR').val(),
      'ctl00$ContentPlaceHolder1$btnSearch': 'Search',
      'ctl00$ContentPlaceHolder1$ddlDistrict': DistrictNo,
      'ctl00$ContentPlaceHolder1$ddlGender': GenderNo,
      'ctl00$ContentPlaceHolder1$ddlPerType': PersonType,
      'ctl00$ContentPlaceHolder1$txtAgeTo': AgeTo,
      'ctl00$ContentPlaceHolder1$txtAgefrom': AgeFrom,
      'ctl00$ContentPlaceHolder1$txtDateRangeFrom': DateFrom,
      'ctl00$ContentPlaceHolder1$txtDateRangeTo': DateTo,
      'ctl00$ContentPlaceHolder1$txtFirstName': FirstName,
      'ctl00$ContentPlaceHolder1$txtLastName': LastName,
      'ctl00$ContentPlaceHolder1$txtMiddleName': MiddleName,
    });

    // Step 3: Send POST request
    let config = {
      method: 'post',
      maxBodyLength: Infinity,
      url: 'https://citizen.mahapolice.gov.in/Citizen/MH/SearcgAccusedArrest.aspx',
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/100.0.4896.75 Safari/537.36',
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'Cookie': cookies.join('; '), // Use dynamic cookies
        'X-Requested-With': 'XMLHttpRequest',
      },
      data: data,
    };

    // Step 4: Fetch the results
    const response = await axios.request(config);
    const $ = cheerio.load(response.data);

    // Process the response...
    const totalRecords = $('#ContentPlaceHolder1_lbltotalrecord').text().trim();
    const arrestedPersons = [];

    $('tr').each((index, element) => {
      if (index < 11) return;

      const columns = $(element).find('td');
      if (columns.length < 10) return;

      arrestedPersons.push({
        srNo: parseInt($(columns[0]).text().trim()),
        name: $(columns[1]).text().trim(),
        gender: $(columns[2]).text().trim(),
        age: parseInt($(columns[3]).text().trim()),
        nationality: $(columns[4]).text().trim(),
        firNo: $(columns[5]).text().trim(),
        district: $(columns[6]).text().trim(),
        policeStation: $(columns[7]).text().trim(),
        personType: $(columns[8]).text().trim(),
        arrestedDateTime: $(columns[9]).text().trim(),
      });
    });

    res.json({
      totalRecords: parseInt(totalRecords),
      arrestedPersons: arrestedPersons
    });

  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});


