  async function loadImageFromFile(filePath) {
    const img = await canvas.loadImage(filePath);
    return img;
  }

  app.post('/compare-faces', async (req, res) => {
    try {
        const { image1 } = req.body;
  
      if (!image1) {
        return res.status(400).send('Please provide URL.');
      }

      const img1 = await loadImageFromUrl(image1);
      const detection1 = await faceapi.detectSingleFace(img1).withFaceLandmarks().withFaceDescriptor();
  
      if (!detection1) {
        return res.json({ result: 'Blue', message: 'No face detected in given image' });
      }
  
      const threshold = 0.6; // Adjust this threshold as needed
  
      const files = await fs.readdir(WANTED_IMAGES_DIR);
      const index = 1
      for (const file of files) {
        const imagePath = path.join(WANTED_IMAGES_DIR, file);
        const img2 = await loadImageFromFile(imagePath);
        const detection2 = await faceapi.detectSingleFace(img2).withFaceLandmarks().withFaceDescriptor();
  
        if (!detection2) {
          continue;
        }
  
        const distance = faceapi.euclideanDistance(detection1.descriptor, detection2.descriptor);
  
        if (distance < threshold) {
          return res.json({ result: 'Red', message: 'Criminal Detected - ' + file });
        }
      }
  
      res.json({ result: 'Blue', message: 'No matching face detected in any image' });
    } catch (error) {
      console.error(error);
      res.status(500).send('An error occurred during face comparison.');
    }
  });

  async function startServer() {
    try {
      await loadModels();
      const PORT = process.env.PORT || 5000;
      app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
    } catch (error) {
      console.error('Failed to start server:', error);
    }
  }
  
  startServer();